// Schema defaults with every mapping iterating in the upstream declaration order
func Defaults() Tree {
	t := defaultsLiteral()
	recordDefaultsOrder(t, "")
	return t
}

// Records the declared key order on a defaults mapping and every mapping below it
func recordDefaultsOrder(m map[string]any, path string) {
	if keys, ok := defaultsKeyOrder[path]; ok {
		SetMappingKeys(m, keys)
	}
	for k, v := range m {
		if child, ok := v.(map[string]any); ok && len(child) > 0 {
			sub := k
			if path != "" {
				sub = path + "\x00" + k
			}
			recordDefaultsOrder(child, sub)
		}
	}
}
